mapper.select:
SELECT DISTINCT A.PORTFOLIO_ID id, A.PORTFOLIO_NAME text, NVL(P.TDY_INTINCEXP,0) object FROM PTL_PORTFOLIO A LEFT JOIN PTL_SEC_ACCT PSA ON A.PORTFOLIO_ID = PSA.PORTFOLIO_ID LEFT JOIN PTL_CAPACCT_INFO PCI ON A.PORTFOLIO_ID = PCI.PORTFOLIO_ID LEFT JOIN ( SELECT psv.TDY_INTINCEXP,psv.PORTFOLIO_ID FROM PTL_SEC_VALUTION psv WHERE psv.CDATE = to_date(#{tradeDate},'yyyy-MM-dd') AND psv.INV_AIM='999999' AND psv.FINPROD_ID = #{finprodIdOrg,jdbcType=VARCHAR}
AND psv.SEC_ACCT_ID = #{chlId,jdbcType=VARCHAR}
)P ON P.PORTFOLIO_ID = A.PORTFOLIO_ID WHERE A.INVEST_YESORNO = 'Y' AND A.PORTFOLIO_ID != #{invTransPortf,jdbcType=VARCHAR} AND A.MDATE >=TO_DATE(#{tradeDate},'yyyy-MM-dd') AND A.VDATE <=TO_DATE(#{tradeDate},'yyyy-MM-dd')
AND PSA.ACCT_NO=#{secAcctId,jdbcType=VARCHAR}
AND PCI.ACCT_NO in (SELECT DISTINCT B.ACCT_NO FROM PTL_CAPACCT_INFO B WHERE B.PORTFOLIO_ID = #{invTransPortf} AND B.ACCT_TYPE = #{capacctType} AND B.CCY = #{ccy})
AND A.PORTFOLIO_ID = #{initValue}
AND ( A.PORTFOLIO_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.PORTFOLIO_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )

SELECT DISTINCT tpd.UNIT_CPRICE as unitCprice,tpda.PORTFOLIO_ID as portfolioId
FROM TRD_PRODUCT_DEAL tpd
LEFT JOIN TRD_PRODUCT_DEAL_ADD tpda
ON tpd.TRADE_ID = tpda.TRADE_ID
WHERE tpd.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND tpd.TRADE_STATUS = #{tardeStatus01,jdbcType=VARCHAR}
AND tpd.IS_CANCEL = #{yesorno_no}
AND tpd.TRADE_DATE = to_date(#{tradeDate},'yyyy-MM-dd')

select
CLOSE_PRICE
from MST_EXCHARGE_QUOTE
where
BASIS_CYY = #{ccy}
and QUOT_CYY = #{cny}
and TRADE_DATE = #{tradDate}

mapper.update:
update
REP_ASSET_DEPT
set
REP_SEND_STATUS = #{YES_OR_NO_Y}
where
REP_FINPROD_ID = #{finprodId}
